const tabId = 248688717;

const analysis = await browserjs(tabId, async () => {
  // Check from current month (Sep 2026) through Sep 2027
  const months = [
    '2026-09-01T00:00:00.000Z',
    '2026-10-01T00:00:00.000Z',
    '2027-06-01T00:00:00.000Z',
    '2027-07-01T00:00:00.000Z',
    '2027-08-01T00:00:00.000Z',
    '2027-09-01T00:00:00.000Z',
  ];

  const results = {};

  for (const m of months) {
    const res = await fetch(`/api/camps/availability/campground/232010/month?start_date=${encodeURIComponent(m)}`);
    if (!res.ok) continue;
    const json = await res.json();

    // Check all dates and statuses across all campsites
    const statusCountsByDate = {};
    for (const [siteId, site] of Object.entries(json.campsites || {})) {
      for (const [dateStr, status] of Object.entries(site.availabilities || {})) {
        if (!statusCountsByDate[dateStr]) statusCountsByDate[dateStr] = {};
        statusCountsByDate[dateStr][status] = (statusCountsByDate[dateStr][status] || 0) + 1;
      }
    }
    results[m.slice(0, 7)] = statusCountsByDate;
  }

  return results;
});

// Let's summarize statuses
const summary = {};
for (const [month, dates] of Object.entries(analysis)) {
  summary[month] = {};
  for (const [dateStr, counts] of Object.entries(dates)) {
    // only keep if not all 'Not Available' or 'Reserved' or let's see what unique statuses exist
    summary[month][dateStr.slice(0, 10)] = counts;
  }
}

console.log("Status summary sample:");
for (const month of Object.keys(summary)) {
  const dates = Object.keys(summary[month]);
  console.log(`Month ${month}: ${dates.length} dates. First date:`, dates[0], summary[month][dates[0]], "Mid date:", dates[Math.floor(dates.length/2)], summary[month][dates[Math.floor(dates.length/2)]]);
}

const tabId = 248688717;

const detailed09 = await browserjs(tabId, async () => {
  const res = await fetch('/api/camps/availability/campground/232010/month?start_date=2026-09-01T00%3A00%3A00.000Z');
  const json = await res.json();
  const dateMap = {};
  for (const [siteId, site] of Object.entries(json.campsites || {})) {
    for (const [dateStr, status] of Object.entries(site.availabilities || {})) {
      const d = dateStr.slice(0, 10);
      if (!dateMap[d]) dateMap[d] = {};
      dateMap[d][status] = (dateMap[d][status] || 0) + 1;
    }
  }
  return dateMap;
});

console.log("2026-09 dates and statuses:", JSON.stringify(detailed09, null, 2));

const tabId = 248688717;

const checkAll = await browserjs(tabId, async () => {
  // Check every month from 2026-09 to 2027-12
  const availableDates = [];
  const statusSummary = {};

  const months = [];
  let y = 2026, m = 9;
  while (y < 2028) {
    const mStr = m < 10 ? `0${m}` : `${m}`;
    months.push(`${y}-${mStr}-01T00:00:00.000Z`);
    m++;
    if (m > 12) {
      m = 1;
      y++;
    }
  }

  for (const start of months) {
    const res = await fetch(`/api/camps/availability/campground/232010/month?start_date=${encodeURIComponent(start)}`);
    if (!res.ok) continue;
    const json = await res.json();
    for (const [siteId, site] of Object.entries(json.campsites || {})) {
      for (const [dateStr, status] of Object.entries(site.availabilities || {})) {
        statusSummary[status] = (statusSummary[status] || 0) + 1;
        if (status === 'Available' || status === 'Open') {
          availableDates.push({ siteId, site: site.site, date: dateStr.slice(0, 10), status });
        }
      }
    }
  }

  return { availableDates, statusSummary };
});

console.log("Status summary across all months:", checkAll.statusSummary);
console.log("Available dates count:", checkAll.availableDates.length);
if (checkAll.availableDates.length > 0) {
  console.log("First 5 available dates:", checkAll.availableDates.slice(0, 5));
}

